from gpiozero import PWMOutputDevice
import sys

# GPIO pins wired to the motor driver inputs (BCM numbering)
MOTOR_PINS = [9, 10, 11, 12, 13]


def apply_state(motor_devices, requested_state):
    """Apply a four-phase motor driver state to the gpiozero devices."""
    # Each entry maps a phase name to its requested duty cycle
    phase_table = {
        "phase1": requested_state[0],
        "phase2": requested_state[1],
        "phase3": requested_state[2],
        "phase4": requested_state[3],
    }
    for phase_name, duty_cycle in phase_table.items():
        device = motor_devices[phase_name]
        device.value = duty_cycle
        print(phase_name, duty_cycle)


def build_devices(pin_list):
    """Create a gpiozero PWM device for each motor driver pin."""
    # Construct one device per phase in the driver
    device_dict = {}
    for phase_index, pin_number in enumerate(pin_list):
        phase_name = "phase%d" % (phase_index + 1)
        device_dict[phase_name] = PWMOutputDevice(pin_number)
    return device_dict


def validate_state(requested_state):
    """Return True when the requested motor state is valid."""
    # Each phase duty cycle must be between 0 and 1
    return all(0.0 <= value <= 1.0 for value in requested_state)


if __name__ == "__main__":
    motor_devices = build_devices(MOTOR_PINS)
    try:
        # Accept a single four-phase duty cycle from the command line
        requested_state = [float(value) for value in sys.argv[1:5]]
        if validate_state(requested_state):
            apply_state(motor_devices, requested_state)
        else:
            print("Error: duty cycle must be between 0 and 1")
    except (ValueError, IndexError):
        print("Usage: python motor.py duty1 duty2 duty3 duty4")
    finally:
        # Release every gpiozero device on exit
        for device in motor_devices.values():
            device.close()

import smbus2
import time

# I2C address of the PCF8574 expander
PCF8574_ADDRESS = 0x27
# I2C bus number on the Raspberry Pi
I2C_BUS_NUMBER = 1


def read_expander(i2c_bus):
    """Read a single byte from the PCF8574 I2C expander."""
    # Read one byte from the expander address
    return i2c_bus.read_byte(PCF8574_ADDRESS)


def is_valid_reading(reading_value):
    """Return True when the reading is within an acceptable range."""
    # Reject obviously invalid values
    return 0 <= reading_value <= 255


def main():
    # Open the I2C bus for the PCF8574 expander
    i2c_bus = smbus2.SMBus(I2C_BUS_NUMBER)
    try:
        # Continuously read and report the expander value
        while True:
            try:
                reading_value = read_expander(i2c_bus)
                if is_valid_reading(reading_value):
                    print("PCF8574 reading:", reading_value)
                else:
                    print("Invalid reading:", reading_value)
            except OSError:
                # Handle a device that does not respond
                print("Expander not responding")
            # Wait before the next reading
            time.sleep(2)
    except KeyboardInterrupt:
        # Exit cleanly on interrupt
        print("Stopping PCF8574 reader")
    finally:
        # Close the I2C bus
        i2c_bus.close()


if __name__ == "__main__":
    main()

import time
import logging
from picamera2 import Picamera2

# Logging setup
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Constants
CAPTURE_INTERVAL_SECONDS = 0.1
IMAGE_FILE_PATH = "image.jpg"


def capture_image(camera_device: Picamera2, file_path: str) -> bool:
    """Captures an image and saves it to the specified file."""
    try:
        camera_device.capture_file(file_path)
        logger.info("Image captured successfully.")
        return True
    except Exception as error:
        logger.error("Image capture failed: %s", error)
        return False


def main():
    """Main function to continuously capture images."""
    try:
        camera = Picamera2()
        camera.start()
        logger.info("Camera initialized.")

        while True:
            if capture_image(camera, IMAGE_FILE_PATH):
                time.sleep(CAPTURE_INTERVAL_SECONDS)
            else:
                time.sleep(CAPTURE_INTERVAL_SECONDS)  # Avoid busy-waiting on failure

    except KeyboardInterrupt:
        logger.info("Interrupted by user.")
    except Exception as error:
        logger.error("An unexpected error occurred: %s", error)
    finally:
        try:
            camera.stop()
            logger.info("Camera stopped.")
        except Exception:
            pass
        logger.info("Exiting program.")


if __name__ == "__main__":
    main()

