from gpiozero import DigitalOutputDevice
import sys

# GPIO pin wired to the relay module (BCM numbering)
RELAY_PIN = 18


def apply_relay_state(relay_device, requested_state):
    """Apply a validated relay state and report the outcome."""
    # Drive the relay pin high for ON, low for OFF
    if requested_state:
        relay_device.on()
    else:
        relay_device.off()
    print("Relay set to: %s" % ("ON" if requested_state else "OFF"))


def validate_reading(reading_value):
    """Return True when the reading is a valid boolean."""
    # Accept only explicit True or False values
    return reading_value in (True, False)


def main():
    # Create the relay output device with pull-down resistor
    relay = DigitalOutputDevice(RELAY_PIN, active_high=True, initial_value=False)
    try:
        # Read a single relay state from the command line
        requested_state = eval(sys.argv[1])
        if validate_reading(requested_state):
            apply_relay_state(relay, requested_state)
        else:
            print("Invalid relay state: %s" % requested_state)
    except (IndexError, NameError):
        print("Usage: python relay_control.py <True|False>")
    finally:
        # Release the GPIO pin on exit
        relay.close()


if __name__ == "__main__":
    main()

from gpiozero import DistanceSensor
import time

# Ultrasonic sensor pins for the hydroponics control system
SENSOR_PINS = [19, 20, 24, 25, 26]

def read_sensors(sensor_list):
    """Read distance from each ultrasonic sensor and print the state."""
    for sensor_index, sensor_device in enumerate(sensor_list):
        try:
            # Get the distance in meters
            distance_value = sensor_device.distance
            print("Sensor %d: %.2f m" % (sensor_index, distance_value))
        except Exception as sensor_error:
            print("Sensor %d error: %s" % (sensor_index, sensor_error))

def main():
    """Initialize sensors and continuously read their states."""
    sensor_objects = []
    try:
        # Create DistanceSensor objects for each pin
        for sensor_pin in SENSOR_PINS:
            sensor_objects.append(DistanceSensor(echo=sensor_pin, trigger=sensor_pin))
        # Continuously monitor the sensors
        while True:
            read_sensors(sensor_objects)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping hydroponics sensor monitoring")
    finally:
        # Release all sensor resources
        for sensor_device in sensor_objects:
            sensor_device.close()

if __name__ == "__main__":
    main()

